/* FurnaceRecipes: one entry per key of smeltingList, in the order the Java
 * HashMap iterates them, with its value. The native port walks these in
 * this order. getSmeltingResult takes the first key whose item matches and
 * whose damage is 32767 or the queried damage. getSmeltingExperience walks
 * experienceList instead and compares the queried stack against each key,
 * which is a *result* stack: SMELT_EXPERIENCE holds those entries, in that
 * map's own order, so the native walk agrees with Java's. */
struct smelting_def {
    struct stack_def input;   /* the map key */
    struct stack_def output;  /* the map value */
    float experience;         /* the value experienceList holds for that output */
};

